package com.example.lending.adapter.out.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.CollectionTable;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Embeddable;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;

import java.time.Instant;
import java.util.ArrayList;
import java.util.List;

@Embeddable
public class CreditCheckEmbeddable {

    @Column(name = "credit_approved", nullable = false)
    private boolean approved;

    @Column(name = "credit_score", nullable = false)
    private int score;

    @Column(name = "credit_checked_at", nullable = false)
    private Instant checkedAt;

    @Column(name = "credit_provider_name")
    private String providerName;

    @Column(name = "credit_provider_version")
    private String providerVersion;

    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "loan_credit_reason_code", joinColumns = @JoinColumn(name = "loan_id"))
    @Column(name = "reason_code", nullable = false)
    private List<String> reasonCodes = new ArrayList<>();

    protected CreditCheckEmbeddable() {
    }

    public CreditCheckEmbeddable(boolean approved, int score, Instant checkedAt, String providerName,
                                 String providerVersion, List<String> reasonCodes) {
        this.approved = approved;
        this.score = score;
        this.checkedAt = checkedAt;
        this.providerName = providerName;
        this.providerVersion = providerVersion;
        this.reasonCodes = new ArrayList<>(reasonCodes);
    }

    public boolean isApproved() {
        return approved;
    }

    public int getScore() {
        return score;
    }

    public Instant getCheckedAt() {
        return checkedAt;
    }

    public String getProviderName() {
        return providerName;
    }

    public String getProviderVersion() {
        return providerVersion;
    }

    public List<String> getReasonCodes() {
        return reasonCodes;
    }
}
